package deploy

const benchmarkWorkflowTmpl = `# {{ .AgentName }} — Benchmark on Release
# Generated by Trovery Forge
#
# Runs performance benchmarks on every release tag.
# Fails the workflow if any benchmark regresses by more than 20%.
name: Benchmark

on:
  push:
    tags: ["v*"]
  workflow_dispatch:

jobs:
  benchmark:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Set up Go
        uses: actions/setup-go@v5
        with:
          go-version: "1.23"

      - name: Run benchmarks
        run: |
          go test ./internal/bench/ -bench=. -benchmem -count=3 -run=^$ | tee bench-results.txt

      - name: Run performance checks
        run: |
          go test ./internal/bench/ -run TestBinarySizeUnder50MB -v
          go test ./internal/bench/ -run TestCLIStartupUnder100ms -v

      - name: Upload benchmark results
        uses: actions/upload-artifact@v4
        with:
          name: benchmark-results
          path: bench-results.txt

      - name: Compare benchmarks (if previous results exist)
        continue-on-error: true
        run: |
          go install golang.org/x/perf/cmd/benchstat@latest
          if [ -f .bench-baseline.txt ]; then
            benchstat .bench-baseline.txt bench-results.txt
          else
            echo "No baseline found. Run 'cp bench-results.txt .bench-baseline.txt' to set one."
          fi
`

func init() {
	// This file just provides the template constant.
	// It's used by deployGitHubActions when generating "all" targets.
}
